rows = json.load(open('.scratch/_p289_ids.json', encoding='utf-8'))
ids = {r['short']: r['candidateId'] for r in rows}
assert set(V) == set(ids), (sorted(set(ids) - set(V)),
                            sorted(set(V) - set(ids)))
assert list(V.keys()) == [r['short'] for r in rows], \
    ('條目順序與 worksheet 不符', list(V.keys())[:5],
     [r['short'] for r in rows][:5])
out = [{'candidateId': ids[r['short']],
        'opinion': V[r['short']][0],
        'reason': V[r['short']][1]} for r in rows]
json.dump(out, open('.scratch/std_p289.json', 'w', encoding='utf-8'),
          ensure_ascii=False, indent=1)
print('wrote %d entries; order matches worksheet' % len(out))
